spec.definitions:
def isPrime (n : Nat) : Bool := n >= 2 && (List.range (n-2) |>.all (fun d => n % (d+2) != 0))

def witnessCheck (p : Nat) : Bool := (Nat.pow 2 (3*p) - 8) % (3*p) == 0

def checkRange : Bool :=
  (List.range 96 |>.filter (fun d => isPrime (d+3)))
    |>.all (fun p => witnessCheck p)
